using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Mechanical;

var doc = Document;
// setup: a mechanical system type, a duct type, and the lowest level
var systemType = new FilteredElementCollector(doc).OfClass(typeof(MechanicalSystemType)).Cast<MechanicalSystemType>().First();
var ductType   = new FilteredElementCollector(doc).OfClass(typeof(DuctType)).Cast<DuctType>().First();
var level      = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var start = new XYZ(0, 0, 10);
var end   = new XYZ(20, 0, 10);

ElementId ductId = null;
// step 1: create the duct from two points inside the connector's transaction
Connector.WithTransaction(doc, () => {
    var duct = Duct.Create(doc, systemType.Id, ductType.Id, level.Id, start, end);
    ductId = duct.Id;
});

// verify: read the created duct's length back
var created = (Duct)doc.GetElement(ductId);
var length  = created.get_Parameter(BuiltInParameter.CURVE_ELEM_LENGTH)?.AsDouble();
return new {
    ductId = ductId.ToString(),
    ductType = ductType.Name,
    systemType = systemType.Name,
    level = level.Name,
    lengthFeet = length
};
